function init(){const root=$('.sp-analysis');if(!root||root.dataset.spOriginalComplete)return;root.dataset.spOriginalComplete='1';for(const h of all('#volume-lab,#statistics',root))for(const e of all('[hidden]',h)){if(e.id==='sp-research-v2'||e.id==='sp-statistics-v2')continue;if(e.querySelector('.sp-metric,.sp-chart-placeholder'))e.hidden=false}for(const e of all('.sp-chart-placeholder',root)){if(e.closest('[id^="sp-extended-"],#sp-research-v2,#sp-statistics-v2'))continue;e.style.removeProperty('display')}for(const id of ['sp-extended-tools','sp-research-v2','sp-statistics-v2','sp-extended-historical-correlation-research','sp-extended-historical-sma-strategy-backtest']){const e=$('#'+id);if(e)e.hidden=true}clearMock();const contractPanel=$('#contract-research');if(contractPanel){const title=$('.sp-contract-heading h3',contractPanel);if(title)title.textContent='Select an option contract';for(const e of all('.sp-contract-heading .sp-muted',contractPanel))e.textContent='Select a scanned contract to inspect actual provider data';contractPanel.removeAttribute('data-sp-selected-contract')}const scanner=$('#stock-scanner');if(scanner){for(const e of all('.sp-demo-label',scanner))e.textContent='PROVIDER SCAN READY';for(const e of all('p,span,div',scanner)){if(e.children.length===0&&/Preview only — scanner engine not connected|3 illustrative results/.test(e.textContent||''))e.textContent='Provider-backed scanner available; limited to selected symbols.'}}const handlers=[['stock-scanner','Run Stock Scan',runStock],['option-scanner','Run Option Scan',runOption],['volume-lab','Analyze Volume',runVolume],['correlation-lab','Calculate Correlation',runCorrelation],['backtesting','Run Historical Test',runBacktest],['statistics','Analyze Historical Pattern',runStatistics]];const byId=new Map(handlers.map(([id,label,fn])=>[id,{label,fn}]));root.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button||!root.contains(button))return;const section=button.closest('.sp-section');const job=section&&byId.get(section.id);if(!job||button.textContent.trim()!==job.label)return;event.preventDefault();event.stopImmediatePropagation();if(button.dataset.spRunning==='1')return;button.dataset.spRunning='1';button.disabled=true;status(section,'Running '+job.label+'…');try{await job.fn()}catch(err){status(section,'Error: '+(err?.message||String(err)));console.error('[StrikePulse '+section.id+']',err)}finally{button.disabled=false;delete button.dataset.spRunning}},true);const c=$('#chart-lab');if(c){for(const id of ['chart-symbol','chart-timeframe','chart-style'])$('#'+id)?.addEventListener('change',()=>runChart().catch(e=>status(c,e.message)));runChart().catch(e=>status(c,e.message));all('input[type=checkbox]',c).forEach(input=>input.addEventListener('change',()=>runChart().catch(e=>status(c,e.message))))}const op=$('#option-scanner');if(op)status(op,'Run Option Scan and select a contract; static demo values removed.');const st=$('#statistics');if(st&&/Opening Range/.test(V('statistical-pattern'))){const choices=$('#statistical-pattern'),fallback=[...choices.options].find(o=>/Volume Spike/.test(o.text));if(fallback){choices.value=fallback.value;status(st,'Default set to Volume Spike; opening-range research requires intraday event data.')}}}
